let count_words words =
  let t = Hashtbl.create 16 in
  List.iter (fun w ->
    let n = Option.value (Hashtbl.find_opt t w) ~default:0 in
    Hashtbl.replace t w (n + 1)) words;
  t

let () =
  let t = count_words ["a"; "b"; "a"; "c"; "a"; "b"] in
  let pairs = Hashtbl.fold (fun k v acc -> (k, v) :: acc) t [] |> List.sort compare in
  List.iter (fun (k, v) -> Printf.printf "%s=%d " k v) pairs;
  print_newline ();
  Printf.printf "%b %b\n" (Hashtbl.mem t "a") (Hashtbl.mem t "z");
  Hashtbl.remove t "a";
  Printf.printf "%d\n" (Hashtbl.length t)

module SMap = Map.Make (String)
module ISet = Set.Make (Int)

let () =
  let m0 = SMap.empty in
  let m1 = SMap.add "b" 2 (SMap.add "a" 1 m0) in
  let m2 = SMap.add "c" 3 m1 in
  SMap.iter (fun k v -> Printf.printf "%s=%d " k v) m2;
  print_newline ();
  Printf.printf "%d %d\n" (SMap.cardinal m1) (SMap.cardinal m2);
  Printf.printf "%s\n" (match SMap.find_opt "z" m2 with None -> "none" | Some _ -> "some");
