let naturals = Seq.iterate (fun n -> n + 1) 0

let () =
  let squares_of_evens =
    naturals |> Seq.filter (fun n -> n mod 2 = 0) |> Seq.map (fun n -> n * n) |> Seq.take 5
  in
  List.iter (Printf.printf "%d ") (List.of_seq squares_of_evens);
  print_newline ();
  let total = naturals |> Seq.take 101 |> Seq.fold_left ( + ) 0 in
  Printf.printf "%d\n" total;
  let calls = ref 0 in
  let s = Seq.map (fun n -> incr calls; n) (Seq.take 3 naturals) in
  Printf.printf "%d\n" !calls;
  ignore (List.of_seq s);
  Printf.printf "%d\n" !calls

